<html><head><meta charset="utf-8"><title>POTRAZ DP2</title><style>body{font:14px Arial;color:#17212b;margin:40px}h1{color:#0e5963;border-bottom:2px solid #2dd4bf;padding-bottom:10px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccd6d8;padding:9px;text-align:left;vertical-align:top}th{background:#edf5f5;width:30%}</style></head><body><h1>POTRAZ Form DP2</h1><p>DPO appointment declaration</p><table><tr><th>Full name</th><td>{{ $form->full_name }}</td></tr><tr><th>Qualifications</th><td>{{ implode(', ', $form->qualifications ?? []) }}</td></tr><tr><th>Certification status</th><td>{{ $form->certification_status }}</td></tr><tr><th>Reporting line</th><td>{{ $form->reporting_line }}</td></tr><tr><th>Official email</th><td>{{ $form->official_email }}</td></tr><tr><th>Official phone</th><td>{{ $form->official_phone }}</td></tr><tr><th>Appointment date</th><td>{{ $form->appointed_at->format('d M Y') }}</td></tr><tr><th>Declaration</th><td>{{ $form->appointment_declaration }}</td></tr></table></body></html>
